import test from 'node:test';
import assert from 'node:assert/strict';
import { buildReleasedFixture } from './fixtures/build-released-fixture.mjs';
import { mkdtemp, mkdir, readFile, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { createHash } from 'node:crypto';
import { readIndependentReviewProgress, resumeIndependentReview } from '../runtime/independent-review-task.mjs';
import { wholeQualitySha256 } from '../runtime/focused-whole-quality-evaluation.mjs';

// Unedited synthetic files generated by e68f56d, including an actual reserved retry and a whitespace recovery.
const golden = await buildReleasedFixture();
const readJSON = async path => JSON.parse(await readFile(path, 'utf8'));
async function legacyTask(t) {
  const root = await mkdtemp(join(tmpdir(), 'review-release-compat-'));
  t.after(() => rm(root, { recursive: true, force: true }));
  const parent = join(root, 'import'), runDir = join(parent, 'run');
  for (const [name, contents] of Object.entries(golden.files)) {
    const target = join(parent, name);
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, contents);
  }
  // Only these two metadata fields are exempted by the released relocation contract.
  const meta = { ...JSON.parse(golden.files['task.json']), runRoot: root, runDir };
  await writeFile(join(parent, 'task.json'), JSON.stringify(meta));
  return { parent, runDir, requestHash: meta.requestHash, meta };
}

test('released snapshot-2 retry and position recovery replay without rewriting the source evidence or redispatching', async t => {
  const task = await legacyTask(t);
  assert.equal((await readIndependentReviewProgress(task)).status, 'complete');
  assert.equal((await resumeIndependentReview({ ...task, analyze: () => assert.fail('unexpected replay dispatch') })).status, 'complete');
  for (const [name, bytes] of Object.entries(golden.files)) {
    if (name !== 'task.json') assert.equal(await readFile(join(task.parent, name), 'utf8'), bytes, name);
  }
});

test('a different focused tool or rules digest is stale, including an almost matching release tuple', async t => {
  const task = await legacyTask(t);
  for (const key of ['toolVersion', 'rulesVersion']) {
    const meta = structuredClone(task.meta);
    meta.versions[key] = '0'.repeat(64);
    await writeFile(join(task.parent, 'task.json'), JSON.stringify(meta));
    assert.equal((await readIndependentReviewProgress(task)).status, 'stale');
  }
});

test('unknown retry engine is rejected even when the changed reservation and event hashes agree', async t => {
  const task = await legacyTask(t);
  const name = Object.keys(golden.files).find(key => key.endsWith('invalid-independent-reading-retry.json'));
  const path = join(task.parent, name), reservation = await readJSON(path);
  reservation.inspection.retryVersions.toolVersion = '1'.repeat(64);
  reservation.inspectionHash = wholeQualitySha256(reservation.inspection);
  const bytes = `${JSON.stringify(reservation, null, 2)}\n`;
  await writeFile(path, bytes);
  const events = golden.files['events.ndjson'].trimEnd().split('\n').map(line => {
    const event = JSON.parse(line);
    if (event.type !== 'independent_reading_retry_reserved') return line;
    return JSON.stringify({ ...event, inspectionHash: reservation.inspectionHash, reservationSha256: createHash('sha256').update(bytes).digest('hex') });
  });
  await writeFile(join(task.parent, 'events.ndjson'), `${events.join('\n')}\n`);
  const result = await readIndependentReviewProgress(task);
  assert.equal(result.status, 'needs_attention'); assert.equal(result.error.code, 'INVALID_READING_RETRY_RESERVATION');
});

test('unknown recovery engine cannot replay a historical proof', async t => {
  const task = await legacyTask(t);
  const name = Object.keys(golden.files).find(key => key.endsWith('/position-recovery.json'));
  const path = join(task.parent, name), proof = await readJSON(path);
  proof.recoveryVersions.toolVersion = '2'.repeat(64);
  await writeFile(path, JSON.stringify(proof));
  const result = await readIndependentReviewProgress(task);
  assert.equal(result.status, 'needs_attention'); assert.equal(result.error.code, 'POSITION_RECOVERY_PROOF_VERSION');
});
